export declare const LIBRARY_SHARE_PAGE = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n  <meta name=\"theme-color\" content=\"#f5f3ef\">\n  <title>Silo shared library</title>\n  <style>\n    :root{color-scheme:light;--ink:#20211f;--muted:#777a72;--line:#e5e3dd;--paper:#f5f3ef;--surface:#fff;--accent:#49664f;--accent-dark:#334b38;--warm:#ebe7de;font:16px/1.45 -apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink)}button,input,select{font:inherit}button{cursor:pointer}.wrap{max-width:1180px;margin:0 auto;padding:env(safe-area-inset-top) 20px calc(32px + env(safe-area-inset-bottom))}.top{display:flex;align-items:center;justify-content:space-between;padding:20px 0 24px;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:11px;font-weight:750;letter-spacing:-.03em;font-size:21px}.mark{width:31px;height:31px;display:grid;place-items:center;background:var(--accent);color:white;border-radius:10px;font-size:17px}.local{font-size:12px;color:var(--muted);border:1px solid var(--line);border-radius:30px;padding:6px 10px}.intro{padding:27px 0 19px}.intro h1{font-size:clamp(25px,6vw,38px);letter-spacing:-.045em;line-height:1.1;margin:0 0 8px}.intro p{color:var(--muted);margin:0}.controls{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px;margin:10px 0 14px}.search{position:relative}.search input{width:100%;height:48px;padding:0 15px 0 44px;border:1px solid var(--line);border-radius:13px;background:var(--surface);outline:none}.search input:focus{border-color:#9aa999;box-shadow:0 0 0 3px #49664f20}.search:before{content:\"\u2315\";position:absolute;left:15px;top:8px;font-size:26px;color:var(--muted)}select,.button{min-height:46px;border:1px solid var(--line);border-radius:12px;background:var(--surface);padding:0 13px;color:var(--ink)}.button.primary{background:var(--accent);border-color:var(--accent);color:white;font-weight:650}.button.primary:disabled{opacity:.42;cursor:not-allowed}.button.quiet{background:transparent}.nav{display:flex;align-items:center;gap:8px;min-height:40px;overflow-x:auto;white-space:nowrap}.crumb{border:0;background:none;padding:5px 2px;color:var(--accent-dark);font-weight:600}.slash{color:#a5a59e}.count{margin-left:auto;color:var(--muted);font-size:13px}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:7px 0 14px}.toolbar-left{display:flex;align-items:center;gap:8px}.toolbar .button{font-size:14px;min-height:40px}.selection{font-size:13px;color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(164px,1fr));gap:12px}.tile{position:relative;overflow:hidden;background:var(--surface);border:1px solid var(--line);border-radius:14px;min-width:0}.thumb{width:100%;aspect-ratio:1.15;object-fit:cover;display:block;background:#e8e6e0;cursor:pointer}.folder-art{aspect-ratio:1.15;display:grid;place-items:center;background:#eeece6;color:#928b7c;font-size:45px;cursor:pointer}.video-tag{position:absolute;top:9px;left:9px;padding:4px 7px;background:#171a17c9;color:#fff;border-radius:6px;font-size:11px}.check{position:absolute;top:9px;right:9px;width:27px;height:27px;accent-color:var(--accent);filter:drop-shadow(0 1px 2px #0004)}.details{padding:9px 10px 10px}.filename{font-size:13px;font-weight:640;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.meta{display:flex;justify-content:space-between;gap:6px;color:var(--muted);font-size:11px;margin-top:3px}.tile-actions{display:flex;gap:6px;margin-top:8px}.tile-actions a,.tile-actions button{flex:1;text-align:center;text-decoration:none;background:var(--warm);border:0;border-radius:8px;padding:7px 5px;color:var(--ink);font-size:12px;font-weight:600}.empty,.status{padding:36px 18px;text-align:center;color:var(--muted)}.status.error{color:#a23e36}.load-more{display:flex;justify-content:center;padding:20px}.modal{position:fixed;inset:0;z-index:5;background:#101210ed;display:grid;grid-template-rows:auto 1fr auto;padding:calc(12px + env(safe-area-inset-top)) 14px calc(14px + env(safe-area-inset-bottom))}.modal-head{display:flex;justify-content:space-between;align-items:center;color:#fff;gap:12px}.modal-head strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.modal button{border:0;border-radius:10px;padding:9px 12px;background:#ffffff20;color:white}.preview{display:grid;place-items:center;min-height:0;padding:14px 0}.preview img,.preview video{max-height:100%;max-width:100%;object-fit:contain;border-radius:7px}.modal-foot{display:flex;justify-content:center}.modal-foot a{display:inline-block;text-decoration:none;background:white;color:var(--ink);padding:11px 18px;border-radius:11px;font-weight:650}.hidden{display:none!important}@media(max-width:560px){.wrap{padding-left:14px;padding-right:14px}.top{padding-top:15px}.controls{grid-template-columns:1fr}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.tile{border-radius:12px}.details{padding:8px}.tile-actions a,.tile-actions button{font-size:11px}.toolbar{align-items:flex-start;flex-direction:column}.toolbar-left{width:100%}.toolbar-left .button{flex:1}.local{font-size:11px}.count{padding-top:6px}}\n  </style>\n</head>\n<body>\n  <main class=\"wrap\">\n    <header class=\"top\"><div class=\"brand\"><span class=\"mark\">S</span><span>Silo share</span></div><span class=\"local\">Private \u00B7 same Wi-Fi</span></header>\n    <section class=\"intro\"><h1>Photos worth sharing.</h1><p>Browse and save originals from this shared Silo library. Use trusted Wi-Fi only; this local connection is not encrypted.</p></section>\n    <section class=\"controls\"><label class=\"search\"><input id=\"query\" type=\"search\" placeholder=\"Search photos and videos\" autocomplete=\"off\" aria-label=\"Search photos and videos\"></label><select id=\"source\" aria-label=\"Choose shared library\"></select></section>\n    <nav id=\"breadcrumbs\" class=\"nav\" aria-label=\"Folder path\"></nav>\n    <div class=\"toolbar\"><div class=\"toolbar-left\"><button id=\"downloadSelected\" class=\"button primary\" disabled>Save selected</button><button id=\"downloadAll\" class=\"button quiet\">Save all</button></div><span id=\"count\" class=\"count\"></span></div>\n    <section id=\"status\" class=\"status\">Connecting to Silo\u2026</section>\n    <section id=\"grid\" class=\"grid\" aria-live=\"polite\"></section>\n    <div id=\"loadMore\" class=\"load-more hidden\"><button class=\"button\" id=\"moreButton\">Load more</button></div>\n  </main>\n  <div id=\"modal\" class=\"modal hidden\" role=\"dialog\" aria-modal=\"true\"><div class=\"modal-head\"><strong id=\"modalName\"></strong><button id=\"closeModal\">Close</button></div><div id=\"preview\" class=\"preview\"></div><div class=\"modal-foot\"><a id=\"modalDownload\">Save to device</a></div></div>\n  <script>\n  (()=>{\n    const token=location.pathname.split('/').filter(Boolean).at(-1);\n    const api=(part)=>'/api/'+token+'/'+part;\n    const el=(id)=>document.getElementById(id);\n    const source=el('source'), query=el('query'), grid=el('grid'), status=el('status'), count=el('count');\n    let folder='', offset=0, nextOffset=null, selected=new Set(), request=0, debounce=null;\n    const bytes=(n)=>{if(!Number.isFinite(n))return '';const units=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return (n<10&&i?n.toFixed(1):Math.round(n))+' '+units[i]};\n    const esc=(s)=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n    const endpoint=(part,params={})=>{const url=new URL(api(part),location.origin);Object.entries(params).forEach(([k,v])=>url.searchParams.set(k,String(v)));return url};\n    const message=(text,error=false)=>{status.textContent=text;status.classList.toggle('error',error);status.classList.toggle('hidden',!text)};\n    function drawCrumbs(){const nav=el('breadcrumbs');nav.replaceChildren();const root=document.createElement('button');root.className='crumb';root.textContent=source.selectedOptions[0]?.textContent||'Library';root.onclick=()=>{folder='';load(true)};nav.append(root);let prefix='';for(const part of folder.split('/').filter(Boolean)){const sep=document.createElement('span');sep.className='slash';sep.textContent='\u203A';nav.append(sep);prefix=prefix?prefix+'/'+part:part;const target=prefix;const button=document.createElement('button');button.className='crumb';button.textContent=part;button.onclick=()=>{folder=target;load(true)};nav.append(button)}}\n    function transfer(items,all=false){let form=document.getElementById('downloadForm');if(!form){form=document.createElement('form');form.id='downloadForm';form.hidden=true;form.method='post';document.body.append(form)}form.action=api('download');form.replaceChildren();const data=document.createElement('input');data.type='hidden';data.name='items';data.value=JSON.stringify(items);form.append(data);const allInput=document.createElement('input');allInput.type='hidden';allInput.name='all';allInput.value=all?'1':'0';form.append(allInput);form.submit()}\n    function tile(item){const article=document.createElement('article');article.className='tile';if(item.kind==='folder'){article.innerHTML='<div class=\"folder-art\" aria-label=\"Folder\">\u25B0</div><div class=\"details\"><div class=\"filename\">'+esc(item.name)+'</div><div class=\"meta\"><span>Folder</span></div></div>';article.querySelector('.folder-art').onclick=()=>{folder=item.relativePath;load(true)};article.querySelector('.filename').onclick=()=>{folder=item.relativePath;load(true)};return article}\n      const previewUrl=endpoint('thumb/'+item.id).toString();article.innerHTML='<img class=\"thumb\" loading=\"lazy\" alt=\"'+esc(item.name)+'\" src=\"'+previewUrl+'\"><span class=\"video-tag '+(item.mediaType==='video'?'':'hidden')+'\">VIDEO</span><input class=\"check\" type=\"checkbox\" aria-label=\"Select '+esc(item.name)+'\"><div class=\"details\"><div class=\"filename\" title=\"'+esc(item.name)+'\">'+esc(item.name)+'</div><div class=\"meta\"><span>'+bytes(item.size)+'</span><span>'+(item.modified?new Date(item.modified).toLocaleDateString():'')+'</span></div><div class=\"tile-actions\"><button type=\"button\">Preview</button><a href=\"'+endpoint('download/'+item.id).toString()+'\">Save</a></div></div>';\n      article.querySelector('.check').checked=selected.has(item.id);article.querySelector('.check').onchange=(event)=>{if(event.target.checked)selected.add(item.id);else selected.delete(item.id);updateSelection()};article.querySelector('.thumb').onclick=()=>openPreview(item);article.querySelector('.tile-actions button').onclick=()=>openPreview(item);return article}\n    function updateSelection(){el('downloadSelected').disabled=!selected.size;el('downloadSelected').textContent=selected.size?'Save selected ('+selected.size+')':'Save selected'}\n    async function load(reset=false){if(reset){offset=0;nextOffset=null;grid.replaceChildren()}const run=++request;message(query.value?'Searching\u2026':'Loading library\u2026');drawCrumbs();const params={source:source.value,folder,offset,limit:72};if(query.value.trim())params.q=query.value.trim();try{const response=await fetch(endpoint('items',params),{cache:'no-store'});if(!response.ok)throw new Error((await response.text())||'Could not load this library.');const data=await response.json();if(run!==request)return;if(reset)grid.replaceChildren();const fragment=document.createDocumentFragment();for(const item of data.items)fragment.append(tile(item));grid.append(fragment);nextOffset=data.nextOffset;el('loadMore').classList.toggle('hidden',nextOffset===null);count.textContent=data.total?data.total.toLocaleString()+' '+(query.value?'matches':'items'):'';message(data.items.length?'':(query.value?'No matches found.':'This folder is empty.'));}catch(error){if(run===request)message(error.message||'Could not load this library.',true)}}\n    function openPreview(item){el('modalName').textContent=item.name;el('modalDownload').href=endpoint('download/'+item.id).toString();const preview=el('preview');preview.replaceChildren();const media=document.createElement(item.mediaType==='video'?'video':'img');media.src=endpoint('media/'+item.id).toString();if(item.mediaType==='video'){media.controls=true;media.playsInline=true;media.preload='metadata'}else media.alt=item.name;preview.append(media);el('modal').classList.remove('hidden')}\n    el('closeModal').onclick=()=>{el('modal').classList.add('hidden');el('preview').replaceChildren()};el('modal').onclick=(event)=>{if(event.target===el('modal'))el('closeModal').click()};\n    el('downloadSelected').onclick=()=>transfer([...selected]);el('downloadAll').onclick=()=>transfer([],true);el('moreButton').onclick=()=>{offset=nextOffset??offset;load(false)};\n    source.onchange=()=>{folder='';selected.clear();updateSelection();load(true)};\n    query.oninput=()=>{clearTimeout(debounce);debounce=setTimeout(()=>{selected.clear();updateSelection();load(true)},350)};\n    fetch(api('sources'),{cache:'no-store'}).then(r=>{if(!r.ok)throw new Error('This Silo share is no longer available.');return r.json()}).then(data=>{source.innerHTML=data.sources.map(s=>'<option value=\"'+esc(s.id)+'\">'+esc(s.label)+'</option>').join('');if(!data.sources.length)throw new Error('No shared libraries are available.');load(true)}).catch(error=>message(error.message,true));\n    updateSelection();\n  })();\n  </script>\n</body>\n</html>";
